/**
 * The incoming-call ringtone: the same original chime the Android app bundles
 * (generated by app/mobile/scripts/generate-ringtone.mjs). Fades in softly,
 * loops until stopped, and stops within a few milliseconds.
 */
export const RINGTONE_URL = "/sounds/yggdras_ring.wav";
export const RING_VOLUME = 0.6;
const FADE_IN = 1.2;
const FADE_OUT = 0.06;

type Context = AudioContext;
let shared: Context | null = null;
let buffer: Promise<AudioBuffer> | null = null;

function context(create: () => Context) {
  if (!shared || shared.state === "closed") shared = create();
  return shared;
}

/**
 * Browsers only allow sound after the person has interacted with the page.
 * Resume the shared context on the first click or key press so a later call can ring.
 */
export function unlockOnFirstGesture(
  target: Pick<Window, "addEventListener" | "removeEventListener">,
  create: () => Context = () => new AudioContext(),
) {
  const unlock = () => {
    void context(create)
      .resume()
      .catch(() => {});
  };
  const options = { capture: true } as const;
  target.addEventListener("pointerdown", unlock, options);
  target.addEventListener("keydown", unlock, options);
  return () => {
    target.removeEventListener("pointerdown", unlock, options);
    target.removeEventListener("keydown", unlock, options);
  };
}

/** Start ringing; the returned function stops it. Never throws: a silent ring still shows. */
export function startRingtone(
  create: () => Context = () => new AudioContext(),
  load: (ctx: Context) => Promise<AudioBuffer> = (ctx) =>
    fetch(RINGTONE_URL)
      .then((r) => {
        if (!r.ok) throw new Error("ringtone unavailable");
        return r.arrayBuffer();
      })
      .then((bytes) => ctx.decodeAudioData(bytes)),
) {
  let stopped = false;
  let stopSound: (() => void) | null = null;
  const ctx = context(create);
  if (!buffer) {
    const loading = load(ctx);
    buffer = loading;
    // A failed load is retried on the next call instead of being cached.
    loading.catch(() => {
      if (buffer === loading) buffer = null;
    });
  }
  const sound = buffer;
  void ctx
    .resume()
    .catch(() => {})
    .then(() => sound)
    .then((audio) => {
      if (stopped) return;
      const source = ctx.createBufferSource();
      const gain = ctx.createGain();
      source.buffer = audio;
      source.loop = true;
      const now = ctx.currentTime;
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.exponentialRampToValueAtTime(RING_VOLUME, now + FADE_IN);
      source.connect(gain).connect(ctx.destination);
      source.start(now);
      stopSound = () => {
        const end = ctx.currentTime;
        gain.gain.cancelScheduledValues(end);
        gain.gain.setValueAtTime(gain.gain.value, end);
        gain.gain.linearRampToValueAtTime(0, end + FADE_OUT);
        try {
          source.stop(end + FADE_OUT);
        } catch {
          // already stopped
        }
      };
    })
    .catch(() => {});
  return () => {
    stopped = true;
    stopSound?.();
    stopSound = null;
  };
}

/** For tests only. */
export function resetRingtone() {
  shared = null;
  buffer = null;
}
